class Cat {
    String name;
    int fish;

    Cat(String name, int fish) {
        this.name = name;
        this.fish = fish;
        System.out.println(name + " 到家了喵");
    }
}

public class Main {
    public static void main(String[] args) {
        Cat c1 = new Cat("小橘", 3);
        Cat c2 = new Cat("狸花", 1);
        System.out.println(c1.name + " " + c1.fish);
        System.out.println(c2.name + " " + c2.fish);
    }
}

